(() => {
  if(new URLSearchParams(location.search).get('edit')!=='1')return;
  const key='laraib-placement-v1';
  const targets={heading:'.inside-heading',title:'.study-title',subtitle:'.inside-heading>p',back:'.back-outside',room:'#room-frame',grass:'#study-grass',ladybugs:'.study-ladybugs',helper:'.smiski-dock',helperMascot:'#assistant-launch',helperInput:'#smiski-question',helperArrow:'.smiski-ask',navigation:'.room-directory',resumeButton:'.room-directory a[href="#resume"]',projectsButton:'.room-directory a[href="#projects"]',educationButton:'.room-directory a[href="#education"]',contactButton:'.room-directory a[href="#contact"]',credits:'.trinket-credits',sound:'#study-sound',speech:'.character-speech'};
  const labels={heading:'Heading · whole group',title:'Study title',subtitle:'Subtitle',back:'Outside link',room:'Room panel · whole group',grass:'ASCII grass',ladybugs:'Ladybugs · whole group',helper:'Smiski bar · whole group',helperMascot:'Helper Smiski',helperInput:'Question input',helperArrow:'Send arrow',navigation:'Navigation · whole group',resumeButton:'Résumé button',projectsButton:'Projects button',educationButton:'Education button',contactButton:'Contact button',credits:'Photo credits',sound:'Sound button',speech:'Speech bubble'};
  for(let i=1;i<=3;i++){targets['ladybug'+i]='[data-placement="ladybug'+i+'"]';labels['ladybug'+i]='Ladybug '+i;}
  for(const section of ['resume','projects','education','contact'])for(const part of ['Icon','Arrow']){const id=section+part;targets[id]='.room-directory a[href="#'+section+'"] '+(part==='Arrow'?'.directory-arrow':section==='resume'||section==='contact'?'.directory-art':'span');labels[id]=section[0].toUpperCase()+section.slice(1)+' '+part.toLowerCase();}
  const empty=()=>({phone:{page:{},scene:{}},desktop:{page:{},scene:{}}});
  const defaults=kind=>({position:kind==='page'?[0,0]:[0,0,0],scale:kind==='page'?[1,1]:[1,1,1],rotation:[0,0,0],visible:true,layer:0});
  const validArray=(v,n,min,max)=>Array.isArray(v)&&v.length===n&&v.every(x=>Number.isFinite(x)&&x>=min&&x<=max);
  function clean(input){const out=empty();for(const mode of ['phone','desktop'])for(const kind of ['page','scene'])for(const [id,value] of Object.entries(input?.[mode]?.[kind]||{})){if(!/^[a-zA-Z][a-zA-Z0-9]*$/.test(id)||kind==='page'&&!targets[id])continue;const v=Array.isArray(value)?{position:value}:value;if(!v||typeof v!=='object')continue;const d=defaults(kind),n=d.position.length;if(validArray(v.position,n,-10000,10000))d.position=[...v.position];if(validArray(v.scale,n,.05,10))d.scale=[...v.scale];if(validArray(v.rotation,3,-3600,3600))d.rotation=[...v.rotation];d.visible=v.visible!==false;if(Number.isInteger(v.layer)&&v.layer>=-100&&v.layer<=1000)d.layer=v.layer;out[mode][kind][id]=d;}return out;}
  let data=empty(),profile=innerWidth<768?'phone':'desktop',selected='page:room',enabled=true,tool='move',drag=null,history=[],lock=false;
  try{data=clean(JSON.parse(localStorage.getItem(key)||JSON.stringify(window.studyLayout||{})));}catch{}
  const panel=document.createElement('aside');panel.id='placement-panel';panel.setAttribute('aria-label','Local layout editor');
  panel.innerHTML=`<details open><summary>✦ Design mode</summary><p>Move, resize, rotate, and tilt individual elements.</p><label>Layout<select id="placement-profile"><option value="phone">Phone</option><option value="desktop">Desktop</option></select></label><label>Element<select id="placement-item"></select></label><label><input id="placement-pieces" type="checkbox"> Show every 3D piece</label><label>Drag action<select id="placement-tool"><option value="move">Move</option><option value="resize">Resize</option><option value="rotate">Rotate</option><option value="tilt">Tilt X / Y</option></select></label><label><input id="placement-enabled" type="checkbox" checked> Editing enabled</label><button id="placement-auto">Auto-select by clicking</button><div class="placement-fields" id="placement-fields"></div><p class="placement-hint">Drag the selected item or use its corner handles to resize. The handle above it rotates. Arrow keys move; Shift moves faster. X/Y use viewport % for page elements, SVG units for tulips, and local units for 3D objects.</p><div><button id="placement-undo">Undo</button><button id="placement-reset">Reset item</button><button id="placement-reset-all">Reset layout</button></div><div><button id="placement-export">Export placements</button><label class="placement-file">Import JSON<input id="placement-import" type="file" accept="application/json"></label></div><button id="placement-exit">Exit editor</button><output id="placement-status" aria-live="polite"></output><p class="placement-hint">Auto-saved in this browser. Export and share the JSON to publish. Phone and desktop presets are separate.</p></details>`;
  document.body.append(panel);if(innerWidth<768)panel.querySelector('details').open=false;
  const overlay=document.createElement('div');overlay.id='placement-box';overlay.hidden=true;
  overlay.innerHTML='<span class="placement-object-name"></span><button data-handle="rotate" class="placement-rotate" aria-label="Rotate selected element">↻</button>'+['nw','ne','sw','se'].map(pos=>'<button data-handle="'+pos+'" class="placement-corner '+pos+'" aria-label="Resize selected element from '+pos+' corner"></button>').join('');document.body.append(overlay);
  const $=id=>panel.querySelector('#'+id),status=$('placement-status');
  const current=()=>{const [kind,id]=selected.split(':');return data[profile][kind][id]||(data[profile][kind][id]=defaults(kind));};
  function remember(){history.push(JSON.stringify(data));if(history.length>60)history.shift();}
  function save(){try{localStorage.setItem(key,JSON.stringify(data));status.textContent='Saved '+profile+' edits locally.';}catch{status.textContent='Storage unavailable; use Export to keep your edits.';}}
  function pageApply(id,t){const el=document.querySelector(targets[id]);if(!el)return;const svg=el.namespaceURI==='http://www.w3.org/2000/svg'&&el.tagName.toLowerCase()!=='svg';el.style.translate=t.position.map((n,i)=>n+(svg?'px':i?'vh':'vw')).join(' ');el.style.scale=t.scale.join(' ');el.style.rotate=t.rotation[2]+'deg';el.style.transform=`rotateX(${t.rotation[0]}deg) rotateY(${t.rotation[1]}deg)`;el.style.transformOrigin='center';el.style.visibility=t.visible===false?'hidden':'';el.style.zIndex=t.layer?String(t.layer):'';if(svg)el.style.transformBox='fill-box';}
  function applyOne(){const [kind,id]=selected.split(':');if(kind==='page')pageApply(id,current());else window.studyPlacement?.set(id,current());updateBox();}
  function apply(){for(const id of Object.keys(targets))pageApply(id,data[profile].page[id]||defaults('page'));for(const id of window.studyPlacement?.list()||[])window.studyPlacement.set(id,data[profile].scene[id]||defaults('scene'),true);window.studyPlacement?.flush();fields();updateBox();}
  function bounds(){const [kind,id]=selected.split(':');return kind==='scene'?window.studyPlacement?.bounds(id):document.querySelector(targets[id])?.getBoundingClientRect();}
  function updateBox(){document.querySelectorAll('.placement-selected').forEach(e=>e.classList.remove('placement-selected'));const b=bounds();overlay.hidden=!enabled||!b||b.width<1||b.height<1;if(overlay.hidden)return;Object.assign(overlay.style,{left:b.left+'px',top:b.top+'px',width:b.width+'px',height:b.height+'px'});const [kind,id]=selected.split(':');overlay.querySelector('.placement-object-name').textContent=kind==='scene'?window.studyPlacement?.label(id)||id:labels[id];}
  const spec=[['position',0,'X',.1],['position',1,'Y',.1],['position',2,'Depth',.1],['scale',0,'Width %',1],['scale',1,'Height %',1],['scale',2,'Depth %',1],['rotation',0,'Tilt X °',1],['rotation',1,'Tilt Y °',1],['rotation',2,'Rotate °',1]];
  function fields(){const t=current(),kind=selected.split(':')[0];$('placement-fields').replaceChildren();for(const [group,index,label,step] of spec){if(kind==='page'&&index===2&&group!=='rotation')continue;const wrapper=document.createElement('label');wrapper.textContent=label;const input=document.createElement('input');input.type='number';input.step=step;input.value=(group==='scale'?t[group][index]*100:t[group][index]).toFixed(group==='position'?2:1);input.dataset.group=group;input.dataset.index=index;if(group==='scale'){input.min=5;input.max=1000;}else{input.min=group==='rotation'?-3600:-10000;input.max=group==='rotation'?3600:10000;}input.addEventListener('focus',remember);input.addEventListener('input',()=>{let value=Number(input.value);if(!input.value||!Number.isFinite(value))return;value=Math.max(Number(input.min),Math.min(Number(input.max),value));current()[group][index]=group==='scale'?value/100:value;applyOne();save();});wrapper.append(input);$('placement-fields').append(wrapper);}const visibility=document.createElement('label');visibility.textContent='Visible';const check=document.createElement('input');check.type='checkbox';check.checked=t.visible!==false;check.onchange=()=>{remember();current().visible=check.checked;applyOne();save();};visibility.append(check);$('placement-fields').append(visibility);if(kind==='page'){const layerLabel=document.createElement('label');layerLabel.textContent='Layer';const layer=document.createElement('input');layer.type='number';layer.min=-100;layer.max=1000;layer.value=t.layer||0;layer.onfocus=remember;layer.oninput=()=>{current().layer=Math.max(-100,Math.min(1000,Math.round(Number(layer.value)||0)));applyOne();save();};layerLabel.append(layer);$('placement-fields').append(layerLabel);}const uniform=document.createElement('button');uniform.textContent='Match height/depth to width';uniform.onclick=()=>{remember();const t=current();t.scale=t.scale.map(()=>t.scale[0]);applyOne();fields();save();};$('placement-fields').append(uniform);}
  function options(){const picker=$('placement-item');picker.replaceChildren();const group=document.createElement('optgroup');group.label='Page elements';for(const id of Object.keys(targets))group.append(new Option(labels[id],'page:'+id));picker.append(group);const scene=document.createElement('optgroup');scene.label='3D room';for(const id of window.studyPlacement?.list()||[]){if(!$('placement-pieces').checked&&/Part\d+$/.test(id))continue;scene.append(new Option(window.studyPlacement.label(id),'scene:'+id));}picker.append(scene);picker.value=selected;}
  function choose(value,locked=false){selected=value;lock=locked;options();fields();updateBox();}
  function move(dx,dy){const [kind,id]=selected.split(':'),t=current();if(kind==='scene'){const v=window.studyPlacement?.move(id,dx,dy);if(v)t.position=v;}else{const el=document.querySelector(targets[id]);if(el?.namespaceURI==='http://www.w3.org/2000/svg'&&el.tagName.toLowerCase()!=='svg'){const matrix=el.parentNode.getScreenCTM();if(matrix){const inv=matrix.inverse();const zero=new DOMPoint(0,0).matrixTransform(inv),delta=new DOMPoint(dx,dy).matrixTransform(inv);t.position[0]+=delta.x-zero.x;t.position[1]+=delta.y-zero.y;}}else{t.position[0]+=dx/innerWidth*100;t.position[1]+=dy/innerHeight*100;}pageApply(id,t);}updateBox();}
  $('placement-profile').value=profile;$('placement-profile').onchange=e=>{profile=e.target.value;history=[];apply();};
  $('placement-item').onchange=e=>choose(e.target.value,true);$('placement-pieces').onchange=options;
  $('placement-tool').onchange=e=>tool=e.target.value;
  $('placement-auto').onclick=()=>{lock=false;status.textContent='Click any element to select it.';};
  $('placement-enabled').onchange=e=>{enabled=e.target.checked;document.body.classList.toggle('placement-mode',enabled);updateBox();};
  $('placement-undo').onclick=()=>{if(history.length){data=clean(JSON.parse(history.pop()));apply();save();}};
  $('placement-reset').onclick=()=>{remember();const [kind,id]=selected.split(':');delete data[profile][kind][id];apply();save();};
  $('placement-reset-all').onclick=()=>{remember();data[profile]={page:{},scene:{}};apply();save();};
  $('placement-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='laraib-study-placements.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  $('placement-import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>250000)throw Error();const value=JSON.parse(await file.text());if(!value.phone&&!value.desktop)throw Error();remember();data=clean(value);apply();save();}catch{status.textContent='Could not import that placement file.';}e.target.value='';};
  $('placement-exit').onclick=()=>{const url=new URL(location.href);url.searchParams.delete('edit');location.href=url.href;};
  document.addEventListener('pointerdown',e=>{if(!enabled||panel.contains(e.target)||e.button!==0)return;const handle=e.target.closest('[data-handle]')?.dataset.handle;let value=handle?selected:null;if(!value&&e.target.id==='room-canvas'&&!lock){const id=window.studyPlacement?.pick(e.clientX,e.clientY);if(id)value='scene:'+id;}if(!value){const [kind,id]=selected.split(':');if(lock&&(kind==='scene'&&e.target.id==='room-canvas'||kind==='page'&&(document.querySelector(targets[id])?.contains(e.target)||id==='grass'&&e.target.id==='room-canvas')))value=selected;else{const candidates=Object.entries(targets).filter(([,selector])=>e.target.closest(selector));candidates.sort((a,b)=>{const x=document.querySelector(a[1]),y=document.querySelector(b[1]);return x===y?0:x.contains(y)?1:y.contains(x)?-1:0;});if(candidates.length)value='page:'+candidates[0][0];}}if(!value)return;e.preventDefault();e.stopImmediatePropagation();choose(value,lock);remember();const b=bounds();drag={id:e.pointerId,x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,handle,tool:handle==='rotate'?'rotate':handle?'resize':tool,initial:structuredClone(current()),box:b?{left:b.left,top:b.top,width:b.width,height:b.height}:{left:e.clientX,top:e.clientY,width:100,height:100}};},true);
  document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;e.preventDefault();e.stopImmediatePropagation();const dx=e.clientX-drag.x,dy=e.clientY-drag.y,t=current();if(drag.tool==='move')move(e.clientX-drag.lastX,e.clientY-drag.lastY);else if(drag.tool==='resize'){const sx=drag.handle?.includes('w')?-1:1,sy=drag.handle?.includes('n')?-1:1;let fx=Math.max(.05,1+sx*dx/Math.max(20,drag.box.width)),fy=Math.max(.05,1+sy*dy/Math.max(20,drag.box.height));if(!e.shiftKey){const f=Math.abs(dx)>Math.abs(dy)?fx:fy;fx=fy=f;}t.scale=t.scale.map((n,i)=>Math.max(.05,Math.min(10,drag.initial.scale[i]*(i===1?fy:fx))));applyOne();}else if(drag.tool==='rotate'){t.rotation[2]=drag.initial.rotation[2]+dx*.6-dy*.3;applyOne();}else{t.rotation[0]=drag.initial.rotation[0]-dy*.5;t.rotation[1]=drag.initial.rotation[1]+dx*.5;applyOne();}drag.lastX=e.clientX;drag.lastY=e.clientY;},true);
  for(const name of ['pointerup','pointercancel'])document.addEventListener(name,e=>{if(!drag)return;e.preventDefault();e.stopImmediatePropagation();drag=null;fields();save();},true);
  document.addEventListener('click',e=>{if(enabled&&!panel.contains(e.target)&&(overlay.contains(e.target)||e.target.closest('#inside-view'))){e.preventDefault();e.stopImmediatePropagation();}},true);
  document.addEventListener('keydown',e=>{if(!enabled||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();e.stopImmediatePropagation();remember();const step=e.shiftKey?10:1;move(e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0,e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0);fields();save();},true);
  window.addEventListener('blur',()=>{if(drag){drag=null;fields();save();}});
  window.addEventListener('study-placement-ready',()=>{options();apply();});
  window.addEventListener('resize',()=>{if(drag)return;const next=innerWidth<768?'phone':'desktop';if(next!==profile){profile=next;$('placement-profile').value=profile;history=[];apply();}updateBox();});
  window.addEventListener('scroll',updateBox,true);new ResizeObserver(updateBox).observe(document.querySelector('#room-frame'));
  document.body.classList.add('placement-mode');options();apply();if(!location.hash||location.hash==='#outside')location.hash='inside';
})();
